    fn account_conversation_id_is_symmetric_and_deterministic() {
        let id = account_conversation_id("alice", "bob");
        assert_eq!(id, account_conversation_id("bob", "alice"));
        assert_eq!(id, account_conversation_id("alice", "bob"));
