        for (device, account) in [(&peer, &account), (&empty_peer, &empty_account)] {
            node.roster.lock().unwrap().update(
                &Announce::new_with_account(device, account, "Legacy", 1),
                IpAddr::V4(Ipv4Addr::LOCALHOST), &node.user_id(),
