        assert!(node.accounts_with_ever_history(&requested).unwrap().is_empty(), "verified account binding alone is not history");
        let conversation = dm_conversation_id(&node.identity.public(), &peer.public());
        let body = MessageBody::new(b"legacy".to_vec(), None).encode();
        match source {
            "sent" => node.sentlog.lock().unwrap().record(conversation, 1, 10, &body).unwrap(),
            "received" => node.received.lock().unwrap().record(conversation, peer.user_id(), 10, &body, EventId::new([17;32])).unwrap(),
            _ => node.received_files.lock().unwrap().record(conversation, peer.user_id(), 10, &body, EventId::new([17;32])).unwrap(),
        }
        let history = node.accounts_with_ever_history(&requested).unwrap();
        assert!(history.contains(&account.account_id()), "{source} route-less device-pair history belongs to its verified human account");
        assert!(!history.contains(&empty_account.account_id()));
        node.sentlog.lock().unwrap().remove_where(|_|true).unwrap();
        node.received.lock().unwrap().remove_where(|_|true).unwrap();
        node.received_files.lock().unwrap().remove_where(|_|true).unwrap();
        assert!(node.accounts_with_ever_history(&requested).unwrap().contains(&account.account_id()), "{source} history stays protected after clear");
    }
}
