#[derive(Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct Author([u8; 32]);

impl Author {
    pub fn from_ed25519(ed25519_pub: [u8; 32]) -> Self {
        Self(ed25519_pub)
    }
    pub fn ed25519_pub(&self) -> &[u8; 32] {
